import os, json, openpyxl, docx, fitz

def read_docx(path):
    print('=== DOCX:', path)
    doc = docx.Document(path)
    for p in doc.paragraphs:
        if p.text.strip(): print(p.text)
    for t in doc.tables:
        for row in t.rows:
            print(' | '.join(c.text.strip() for c in row.cells))

def read_pdf(path):
    print('=== PDF:', path)
    doc = fitz.open(path)
    for i, page in enumerate(doc):
        print(f'--- Page {i+1} ---')
        print(page.get_text())

def read_xlsx(path):
    print('=== XLSX:', path)
    wb = openpyxl.load_workbook(path, data_only=True)
    for name in wb.sheetnames:
        print(f'--- Sheet: {name} ---')
        ws = wb[name]
        for row in ws.iter_rows(values_only=True):
            if any(x is not None for x in row):
                print(row)

print(open('15_model/DC2-A-STR_Model_Note.txt').read())
read_docx('project/00_admin/OBD-DC2-A_Owners_Basis_of_Design_excerpt.docx')
read_pdf('project/00_admin/T-118_Document_Transmittal.pdf')
